cat > /tmp/build_payload_script.json << 'SCRIPTEOF'
{
  "script": "const doc = ($vars.extractInvoiceFields.output.ExtractionResult || {}).ResultsDocument || {};
const fields = doc.Fields || [];
const tables = doc.Tables || [];

// NOTE: field/column names below are common IXP invoice-taxonomy guesses.
// IT must confirm the real taxonomy (uip ixp deployments get-taxonomy) and
// adjust these names to match InvoiceIXP's trained fields before go-live.
function fieldValue(name) {
  const f = fields.find(function (x) { return x.FieldName === name; });
  return (f && f.Values && f.Values[0]) || null;
}

const table = tables[0] || null;
const rows = (table && table.Values) || [];

let headerMap = {};
rows.forEach(function (row) {
  (row.Cells || []).forEach(function (cell) {
    if (cell.IsHeader) {
      const values = cell.Values || [];
      const text = (values[0] && values[0].Value) || "";
      headerMap[cell.ColumnIndex] = text.toLowerCase();
    }
  });
});

function pickColumn(row, keyword) {
  const cells = row.Cells || [];
  const match = cells.find(function (c) { return (headerMap[c.ColumnIndex] || "").indexOf(keyword) >= 0; });
  const values = match ? (match.Values || []) : [];
  return (values[0] && values[0].Value) || null;
}

const lineItems = [];
rows.forEach(function (row) {
  const isHeaderRow = (row.Cells || []).some(function (c) { return c.IsHeader; });
  if (isHeaderRow) return;
  lineItems.push({
    description: pickColumn(row, "descr"),
    quantity: pickColumn(row, "qty") || pickColumn(row, "quantity"),
    unitPrice: pickColumn(row, "price") || pickColumn(row, "rate"),
    lineTotal: pickColumn(row, "amount") || pickColumn(row, "total")
  });
});

return {
  invoiceNumber: fieldValue("Invoice Number") || fieldValue("InvoiceNumber") || fieldValue("Invoice #"),
  vendorName: fieldValue("Vendor Name") || fieldValue("Vendor") || fieldValue("Supplier"),
  invoiceDate: fieldValue("Invoice Date") || fieldValue("Date"),
  totalAmount: fieldValue("Total") || fieldValue("Invoice Total") || fieldValue("Amount Due") || fieldValue("Total Amount"),
  lineItems: lineItems
};"
}
SCRIPTEOF
